require_once __DIR__.'/../includes/verificar_sesion.php';$roles_permitidos=['administrador'];require_once __DIR__.'/../includes/verificar_rol.php';require_once __DIR__.'/../config/conexion.php';$errores=[];if($_SERVER['REQUEST_METHOD']==='POST'){$nombre=trim($_POST['nombre']??'');$correo=trim($_POST['correo']??'');$rol=$_POST['rol']??'especialista';if($nombre===''||!filter_var($correo,FILTER_VALIDATE_EMAIL))$errores[]='Nombre y correo son obligatorios.';if(!in_array($rol,['cliente','especialista'],true))$errores[]='Rol inválido.';if(!$errores){$q=$pdo->prepare('SELECT id_usuario FROM usuarios WHERE correo=?');$q->execute([$correo]);if($q->fetch())$errores[]='El correo ya existe.';else{$q=$pdo->prepare('INSERT INTO usuarios (nombre,correo,contrasena,rol) VALUES (?,?,?,?)');$q->execute([$nombre,$correo,'retrofix123',$rol]);establecer_mensaje('exito','Usuario creado. Contraseña inicial: retrofix123');redirigir('usuarios.php');}}}$usuarios=$pdo->query('SELECT * FROM usuarios ORDER BY fecha_registro DESC')->fetchAll();$titulo_pagina='Usuarios';$ruta_base='../';require_once __DIR__.'/../includes/encabezado.php';
?><div class="cabecera-panel"><div><span class="etiqueta">PERSONAL Y CLIENTES</span><h1>Usuarios</h1><p>Administra los accesos al sistema.</p></div></div><?php if($errores): ?><div class="alerta alerta-error"><?= escapar(implode(' ',$errores)) ?></div><?php endif; ?><section class="formulario-panel" style="margin-bottom:20px"><h2>Registrar usuario interno</h2><form method="post" class="formulario"><div class="rejilla-tres"><label>Nombre<input name="nombre" required></label><label>Correo<input type="email" name="correo" required></label><label>Rol<select name="rol"><option value="especialista">Especialista</option><option value="cliente">Cliente</option></select></label></div><button class="boton" type="submit">Crear usuario</button></form></section><section class="tabla-contenedor"><table class="tabla"><thead><tr><th>Nombre</th><th>Correo</th><th>Rol</th><th>Registro</th><th>Estado</th></tr></thead><tbody><?php foreach($usuarios as $u): ?><tr><td><?= escapar($u['nombre']) ?></td><td><?= escapar($u['correo']) ?></td><td><span class="estado"><?= escapar(ucfirst($u['rol'])) ?></span></td><td><?= date('d/m/Y',strtotime($u['fecha_registro'])) ?></td><td><?= escapar($u['estado']) ?></td></tr><?php endforeach; ?></tbody></table></section><?php require_once __DIR__.'/../includes/pie.php'; ?>


